// ============================================================
// WF2-3 · Code · "คำนวณคงเหลือจากยอดผลิตจริง (re-plan)"
// อ่าน 4 โหนด Google Sheets แยก (executeOnce): $('อ่าน Planning') $('อ่านรายการ T1') $('อ่าน map') $('อ่าน Loss report')
//
// รวมยอดของดี "สะสมตั้งแต่วันเริ่มแผนแรกสุด" ต่อ (core,เครื่อง) -> คงเหลือ = ยอดตั้งต้น - ผลิตแล้ว
// ส่งออกให้ flow วางแผน (คงเหลือ = จำนวนที่ต้องผลิตเพิ่ม (ใบ) เพื่อจัดเวลา) + พก _ยอดตั้งต้น/_ผลิตแล้ว/_วันเริ่มแผน
// ============================================================

const pad = n => String(n).padStart(2, '0');
const num = v => { const s = String(v ?? '').replace(/[,\s]/g, ''); if (s === '' || s === '-') return null; const n = parseFloat(s); return isNaN(n) ? null : n; };
const core = s => String(s ?? '').split('|')[0].trim();
const normMachine = m => { m = String(m ?? '').trim().toUpperCase(); if (m === 'TE1') return 'TE'; return m; };
function toYMD(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date && !isNaN(v)) return `${v.getUTCFullYear()}-${pad(v.getUTCMonth()+1)}-${pad(v.getUTCDate())}`;
  const s = String(v).trim(); if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) { const n = parseFloat(s); if (n > 20000 && n < 80000) { const d = new Date(Date.UTC(1899,11,30) + Math.round(n)*86400000); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`; } }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) { let Y=+m[1]; if(Y>2400)Y-=543; return `${Y}-${pad(+m[2])}-${pad(+m[3])}`; }
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/); if (m) { let Y=+m[3]; if(Y>2400)Y-=543; if(Y<100)Y+=2000; return `${Y}-${pad(+m[2])}-${pad(+m[1])}`; }
  const d = new Date(s); return isNaN(d) ? null : `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`;
}
const ymd2dmy = y => { if (!y) return ''; const [Y,M,D] = y.split('-'); return `${D}/${M}/${Y}`; };
function pick(row, subs) { const keys = Object.keys(row); for (const s of [].concat(subs)) { const k = keys.find(k => k.replace(/\s+/g,' ').includes(s)); if (k) return row[k]; } return undefined; }
function grab(nodeName) { try { return $(nodeName).all().map(i => i.json); } catch (e) { return []; } }
// อ่านแต่ละชีตจากโหนด Google Sheets แยก (อ้าง gid) — เลี่ยงปัญหา batchGet: ส่ง ranges ซ้ำไม่ได้ + ชื่อชีตมี |
const planningRows = grab('อ่าน Planning');
const raykarRows   = grab('อ่านรายการ T1');
const mapRowsB     = grab('อ่าน map');

// วันนี้ (เวลาไทย)
const nowBkk = new Date(Date.now() + 7*3600*1000);
const TODAY = `${nowBkk.getUTCFullYear()}-${pad(nowBkk.getUTCMonth()+1)}-${pad(nowBkk.getUTCDate())}`;

// ---- map: ชื่อย่อ(loss) -> ชื่อในแผน(core) ----
const MAP = {};
for (const r of mapRowsB) {
  const from = String(pick(r, ['ชื่อในรายงาน']) ?? '').trim();
  const to = String(pick(r, ['ชื่อในแผน']) ?? '').trim();
  if (from && to && to !== '—') MAP[from] = to;
}
const mapCore = p => MAP[String(p ?? '').trim()] || null;

// ---- Planning เดิม: aggregate ต่อ (core, เครื่อง) ----
const agg = {};
for (const r of planningRows) {
  const full = String(pick(r, ['ชื่อสินค้า']) ?? '').trim();
  const machine = String(pick(r, ['เครื่องจักร']) ?? '').trim();
  const qty = num(pick(r, ['จำนวนที่ต้องผลิตเพิ่ม'])) || 0;
  if (!full || !machine || qty <= 0) continue;
  const c = core(full), key = c + '¦' + machine;
  const startY = toYMD(pick(r, ['วันที่ผลิต']));
  if (!agg[key]) agg[key] = { core: c, full, machine, code: String(pick(r,['รหัสสินค้า']) ?? '').trim(), qty: 0, delivery: '', origStart: null };
  const a = agg[key];
  a.qty += qty;
  const del = String(pick(r, ['วัน Delivery']) ?? '').trim();
  if (del && (!a.delivery)) a.delivery = del;
  if (startY && (!a.origStart || startY < a.origStart)) a.origStart = startY;
  if (!a.code) a.code = String(pick(r,['รหัสสินค้า']) ?? '').trim();
}

// ---- รายการ T1: earliest 'วันที่เริ่มผลิตสินค้า' ต่อ (core, เครื่อง) = fallback วันเริ่มแผน ----
const raykarStart = {};
for (const r of raykarRows) {
  const machine = String(pick(r, ['เครื่องจักร']) ?? '').trim();
  const startY = toYMD(pick(r, ['วันที่เริ่มผลิตสินค้า']));
  if (!machine || !startY) continue;
  for (const slot of ['ชื่อสินค้า แม่พิมพ์ตัวที่ 1','ชื่อสินค้า แม่พิมพ์ตัวที่ 2','ชื่อสินค้า แม่พิมพ์ตัวที่ 3','ชื่อสินค้า แม่พิมพ์ตัวที่ 4']) {
    const nm = core(pick(r, [slot]));
    if (!nm) continue;
    const key = nm + '¦' + machine;
    if (!raykarStart[key] || startY < raykarStart[key]) raykarStart[key] = startY;
  }
}

// ---- Loss: index ของดี ต่อ (เครื่องnorm, core, วันที่) ----
const loss = grab('อ่าน Loss report');
console.log(`[re-plan/debug] Planning=${planningRows.length} รายการ=${raykarRows.length} map=${Object.keys(MAP).length} loss=${loss.length} | agg(core,เครื่อง)=${Object.keys(agg).length}`);
if (planningRows.length === 0) {
  throw new Error(`[re-plan] อ่านชีต Planning ไม่ได้ (0 แถว) — เช็คโหนด "อ่าน Planning" ว่าอ่านแท็บ 'TPI | Production Planning| 2026' (gid 1559920379) แล้วมีข้อมูล`);
}
if (Object.keys(agg).length === 0) {
  throw new Error(`[re-plan] Planning ${planningRows.length} แถว แต่รวม (core,เครื่อง) ได้ 0 — เช็คคอลัมน์ 'ชื่อสินค้า'/'เครื่องจักร'/'จำนวนที่ต้องผลิตเพิ่ม (ใบ)' ในชีต Planning (หัวตารางแถว 1) · ตัวอย่างคีย์แถวแรก: ${JSON.stringify(Object.keys(planningRows[0]||{}))}`);
}
function producedFor(machine, coreName, fromYMD) {
  let s = 0;
  for (const L of loss) {
    const g = num(pick(L, ['ของดี'])); if (g === null) continue;
    if (normMachine(pick(L, ['เครื่อง'])) !== machine) continue;
    if (mapCore(pick(L, ['ชื่อสินค้า'])) !== coreName) continue;
    const dy = toYMD(pick(L, ['วันที่'])); if (!dy) continue;
    if (fromYMD && dy < fromYMD) continue;
    if (dy > TODAY) continue;
    s += g;
  }
  return s;
}

// ---- คำนวณคงเหลือ ----
const out = [];
let skipDone = 0;
for (const key in agg) {
  const a = agg[key];
  // 'วันเริ่มแผน' (นับผลิตแล้วสะสมตั้งแต่วันนี้): วันที่ผลิต(Planning, คงไว้ข้ามรอบ) > วันเริ่มในรายการเดิม > วันนี้
  // ไม่ย้อนไปวันที่ผลิตจริงแรกสุด เพราะ backlog เป็นยอด ณ เวลาตั้งแผน การนับก่อนตั้งแผนจะหักซ้ำ
  const origStart = a.origStart || raykarStart[key] || TODAY;
  const produced = producedFor(a.machine, a.core, origStart);
  const remaining = Math.round(a.qty - produced);
  if (remaining <= 0) { skipDone++; continue; }   // ผลิตครบแล้ว -> เอาออกจากแผน
  out.push({ json: {
    'ชื่อสินค้า': a.full,
    'รหัสสินค้า': a.code,
    'จำนวนที่ต้องผลิตเพิ่ม (ใบ)': remaining,   // ใช้คงเหลือ จัดเวลา/เครื่องใหม่
    'วัน Delivery': a.delivery,
    'วันที่ผลิต': '',                          // ให้ scheduler เริ่มจากวันนี้
    'เครื่องจักร': '',                          // ให้ v2.0 เลือกเครื่องใหม่
    '_ยอดตั้งต้น': a.qty,                       // คงไว้เขียนกลับ Planning
    '_ผลิตแล้ว': produced,
    '_วันเริ่มแผน': ymd2dmy(origStart),         // preserve วันเริ่มแผนเดิม
  } });
}
console.log(`[re-plan] วันนี้=${TODAY} | (core,เครื่อง) ในแผน ${Object.keys(agg).length} | ยังต้องผลิต ${out.length} | ผลิตครบแล้ว ${skipDone}`);
return out;

// ============================================================
// WF2-3 · Code · "กำหนดเครื่องจักร + คำนวณเวลาผลิต" (v2.0)
// Standalone — ความรู้ฝังในไฟล์ ไม่ต้องอ่าน spreadsheet DATA
// v2.0: สร้างตารางจากข้อมูลจริงครบทุกเครื่อง (PF8/3,5,7,8, TE,
//       ASB250/3) — %ของดีครบ → จัดอันดับข้ามเครื่องทำงานจริง
//       (ไม่รวมเครื่องสวมฟิล์ม NO.1/5/6 และหลอดพรีฟอร์ม KM175)
// Input : items ที่มี "ชื่อสินค้า" + "จำนวนที่ต้องผลิตเพิ่ม (ใบ)"
// Output: format เดียวกับ prompt/skill — พร้อมเขียนลง sheet T1
// ============================================================

const CONFIG = {
  ROUND_HOURS_DP: 2,          // ทศนิยมเวลาผลิต
  WEIGHT_FACTOR: 2,           // น้ำหนักต่าง 1 g = 2 คะแนนระยะห่าง
  VOLUME_FACTOR: 0.01,        // ขนาดต่าง 100 ml = 1 คะแนนระยะห่าง
  LOW_CONFIDENCE_DISTANCE: 8, // เกินนี้ = ประมาณการความเชื่อมั่นต่ำ
};

