: 1041.6}}, "ขวดฉั่วฮะเส็ง 380": {"TE": {"good": 100, "ct": 3.91, "cap": 1841.4}}, "ขวดซากุระ 700": {"TE": {"good": 99.91, "ct": 4.89, "cap": 1472.4}}, "ขวดปาปาแพค 150 KR": {"TE": {"good": 99.01, "ct": 4.45, "cap": 1618.0}}, "ขวดทานตะวัน 730": {"TE": {"good": 99.74, "ct": 4.42, "cap": 1629.0}}, "ขวดกรุงสยาม 450 V2": {"TE": {"good": 98.88, "ct": 4.26, "cap": 1690.1}}, "ขวดอินโนเฟรช 465": {"TE": {"good": 96.59, "ct": 5.23, "cap": 1375.6}}};

const core = s => String(s || '').split('|')[0].trim();
const num  = v => Number(String(v ?? '').replace(/,/g, '')) || 0;
function pick(row, prefix) { for (const k of Object.keys(row)) if (k.replace(/\s+/g, ' ').trim().startsWith(prefix)) return row[k]; return ''; }
const fnum = v => { const n = parseFloat(String(v ?? '').replace(/,/g, '')); return isNaN(n) ? null : n; };

// ---- อ่านซ่อม+ไฟ ต่อเครื่อง จาก MachineStats ----
const REPAIR = {}, ENERGY = {};
try {
  for (const it of $('อ่าน MachineStats').all()) {
    const m = String(pick(it.json, 'เครื่องจักร') || '').trim();
    if (!m) continue;
    REPAIR[m] = fnum(pick(it.json, 'ซ่อมเฉลี่ย'));
    ENERGY[m] = fnum(pick(it.json, 'ไฟเฉลี่ย'));
  }
} catch (e) { /* ไม่มี node → ซ่อม/ไฟ = null → คะแนนกลาง 0.5 */ }

// [machine_status] เครื่องที่ "ใช้งานได้" — กรองเครื่องเสียออกจากการเลือก
const _nm = m => { m = String(m || '').trim().toUpperCase(); return m === 'TE1' ? 'TE' : m; };
const USABLE = new Set(); let hasStatus = false;   // hasStatus=false → ไม่มีชีต → ไม่กรอง
try {
  for (const it of $('อ่านสถานะเครื่อง').all()) {
    const s = pick(it.json, 'สถานะ'); if (s == null) continue;
    const m = _nm(pick(it.json, 'เครื่องจักร')); if (!m) continue;
    hasStatus = true;
    if (!/เสีย|พัง|ปิด|หยุด|ซ่อม/.test(String(s))) USABLE.add(m);
  }
} catch (e) { /* ไม่มี node สถานะ → ไม่กรอง */ }
const _ok = m => !hasStatus || USABLE.has(_nm(m));

// ratio-to-best: ดีสุด=1 ; ตัวอื่น=สัดส่วน ; ไม่มีข้อมูล=0.5
function dimScore(vals, higherBetter) {
  const nums = vals.filter(v => v != null);
  if (!nums.length) return vals.map(() => 0.5);
  const best = higherBetter ? Math.max(...nums) : Math.min(...nums);
  return vals.map(v => { if (v == null) return 0.5; if (higherBetter) return best ? v / best : 1; return v ? best / v : 1; });
}

const jobCount = {};
const items = $input.all().map(it => ({ ...it.json }))
  .sort((a, b) => num(b['จำนวนที่ต้องผลิตเพิ่ม (ใบ)']) - num(a['จำนวนที่ต้องผลิตเพิ่ม (ใบ)']));
const out = [];
for (const r of items) {
  const p = core(r['ชื่อสินค้า']);
  const qmap = QUALITY[p];
  const prev = r['หมายเหตุ'] ? ' | ' + r['หมายเหตุ'] : '';

  // fix3: v2.0 ใช้ "กฎพิเศษ" (เครื่องบังคับตามน้ำหนัก) → ไม่ override แต่ยังนับโหลด
  if (String(r['แหล่งข้อมูล'] ?? '').trim() === 'กฎพิเศษ') {
    const m = String(r['เครื่องจักร'] ?? '').trim();
    if (m) jobCount[m] = (jobCount[m] || 0) + 1;
    const _w = (m && !_ok(m)) ? ' ⚠ เครื่องเสีย ต้องย้ายมือ' : '';
    r['หมายเหตุ'] = `[combined] ไม่เลือกใหม่ — กฎพิเศษน้ำหนัก (v2.0) บังคับ ${m}${_w}` + prev;
    out.push({ json: r });
    continue;
  }

  if (qmap && Object.keys(qmap).length) {
    let cands = Object.keys(qmap).filter(_ok);
    if (!cands.length) {   // เครื่องที่มีประวัติผลิตสินค้านี้ เสียหมด → คงผล v2.0 + เตือนย้ายมือ
      const m0 = String(r['เครื่องจักร'] ?? '').trim();
      r['หมายเหตุ'] = `[combined] ⚠ เครื่องที่ผลิต "${p}" ได้ เสียหมด (${Object.keys(qmap).join(',')}) — คงผล v2.0 (${m0})` + prev;
      out.push({ json: r }); continue;
    }
    const qs = dimScore(cands.map(m => 100 - qmap[m].good), false);   // fix1: ใช้ %ของเสีย (น้อย=ดี) — %ของดี บีบความต่างจนแบน
    const rs = dimScore(cands.map(m => (m in REPAIR ? REPAIR[m] : null)), false);
    const es = dimScore(cands.map(m => (m in ENERGY ? ENERGY[m] : null)), false);
    const score = cands.map((m, i) => WEIGHT.q * qs[i] + WEIGHT.r * rs[i] + WEIGHT.e * es[i]);
    const top = Math.max(...score);
    const thresh = top * (1 - BAND_PCT);
    const band = cands.map((m, i) => ({ m, i, s: score[i] })).filter(x => x.s >= thresh);
    band.sort((a, b) => ((jobCount[a.m] || 0) - (jobCount[b.m] || 0)) || (b.s - a.s));
    const chosen = band[0].m, info = qmap[chosen];
    jobCount[chosen] = (jobCount[chosen] || 0) + 1;
    r['เครื่องจักร'] = chosen;
    r['Cycle Time (s)'] = info.ct;
    r['กำลังผลิตจริง (ใบ/ชม)'] = info.cap;
    r['เวลาผลิต (ชม)'] = info.cap ? Math.round(num(r['จำนวนที่ต้องผลิตเพิ่ม (ใบ)']) / info.cap * 100) / 100 : null;
    r['%ของดีอ้างอิง'] = info.good;
    r['แหล่งข้อมูล'] = 'combined(3มิติ+band+โหลด)';
    r['หมายเหตุ'] = `[combined] เลือก ${chosen} (โหลด ${jobCount[chosen]}) | คะแนน: ` +
      cands.map((m, i) => `${m}:${score[i].toFixed(3)}${score[i] >= thresh ? '*' : ''}[ดี${qmap[m].good}/ซ่อม${(m in REPAIR ? REPAIR[m] : '-')}/ไฟ${(m in ENERGY ? ENERGY[m] : '-')}]`).join(' ') +
      ` band≥${thresh.toFixed(3)}` + prev;
  } else {
    const _w2 = (() => { const m0 = String(r['เครื่องจักร'] ?? '').trim(); return (m0 && !_ok(m0)) ? ' ⚠ เครื่องเสีย ต้องย้ายมือ' : ''; })();
    r['หมายเหตุ'] = `[combined] ไม่มีข้อมูลคุณภาพรายเครื่องของ "${p}" คงผล v2.0${_w2}` + prev;
  }
  out.push({ json: r });
}
return out;

return (function(){
